"use client";

import React from "react";
import { Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useLanguage } from "@/contexts/LanguageContext";

interface ERPNextConfigCardProps {
  url: string;
  onUrlChange: (val: string) => void;
  onSave: () => void;
  isSaving?: boolean;
}

export function ERPNextConfigCard({
  url,
  onUrlChange,
  onSave,
  isSaving,
}: ERPNextConfigCardProps) {
  const { language } = useLanguage();
  const isRTL = language === "ar";

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave();
  };

  return (
    <div className="rounded-xl border border-gray-200 dark:border-neutral-800 bg-white dark:bg-neutral-900 p-5 shadow-2xs space-y-2">
      <label className="text-xs font-semibold text-gray-700 dark:text-gray-300 block">
        ERPNext URL
      </label>

      <form onSubmit={handleSubmit} className="flex items-center gap-2">
        <Input
          type="url"
          value={url}
          onChange={(e) => onUrlChange(e.target.value)}
          placeholder="https://crm.advixs.com"
          className="h-9 text-xs sm:text-sm bg-white dark:bg-neutral-950 border-gray-200 dark:border-neutral-800 shadow-2xs rounded-lg flex-1"
          required
        />

        <Button
          type="submit"
          disabled={isSaving}
          className="h-9 bg-teal-700 hover:bg-teal-800 text-white text-xs font-medium px-4 rounded-lg shadow-xs shrink-0 cursor-pointer"
        >
          {isSaving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : null}
          <span>{isRTL ? "حفظ" : "Save"}</span>
        </Button>
      </form>

      <p className="text-xs text-gray-400 dark:text-gray-500 leading-relaxed">
        {isRTL
          ? "استخدم اسم النطاق (Domain name) وليس عنوان IP — تم إصدار شهادة SSL للنطاق، ويرفض المتصفح تضمين الإطار عندما لا يتطابق الاسم."
          : "Use the domain name, not an IP address — the SSL certificate is issued for the domain, and the browser refuses the frame when the name does not match."}
      </p>
    </div>
  );
}
